from confluent_kafka import Consumer,TopicPartition,OFFSET_STORED
def checkpoint_probe(config,topic,group,count,commit):
    cfg=dict(config,**{'group.id':group,'enable.auto.commit':False,'auto.offset.reset':'earliest'})
    c=Consumer(cfg)
    def take(client):
        for _ in range(100):
            m=client.poll(.1)
            if m is not None and not m.error():return m
        raise TimeoutError('message')
    try:
        c.assign([TopicPartition(topic,0,OFFSET_STORED)])
        taken=[take(c).offset() for _ in range(count)]
        position=c.position([TopicPartition(topic,0)])[0].offset
        if commit:c.commit(offsets=[TopicPartition(topic,0,position)],asynchronous=False)
        saved=c.committed([TopicPartition(topic,0)],timeout=8)[0].offset
    finally:c.close()
    c=Consumer(cfg)
    try:
        c.assign([TopicPartition(topic,0,OFFSET_STORED)])
        resumed=take(c).offset()
    finally:c.close()
    return {'taken':taken,'position':position,'committed':saved,'resumed':resumed}

