import time
def hold_and_resume(consumer,partitions,duration):
    consumer.pause(partitions)
    start=time.monotonic();delivered=0
    try:
        while time.monotonic()-start<duration:
            message=consumer.poll(min(.05,max(0,duration-(time.monotonic()-start))))
            if message is not None and not message.error():delivered+=1
    finally:consumer.resume(partitions)
    return delivered

