from confluent_kafka import Consumer,TopicPartition
def locate(config,topic,partition,threshold):
    c=Consumer(dict(config,**{'group.id':'time-query','enable.auto.commit':False}))
    try:
        found=c.offsets_for_times([TopicPartition(topic,partition,threshold)],timeout=8)[0]
        if found.offset<0:return None
        c.assign([found])
        for _ in range(100):
            message=c.poll(.1)
            if message is not None and not message.error():
                kind,when=message.timestamp()
                return {'offset':message.offset(),'timestamp_type':kind,'timestamp':when,'value':message.value()}
        raise TimeoutError('timestamp lookup read')
    finally:c.close()

