import hashlib,os,pathlib,stat,tempfile,re
def load_ref(store,reference):
    digest=reference.get('sha256')
    if not isinstance(digest,str) or not re.fullmatch('[0-9a-f]{64}',digest):raise ValueError('invalid immutable object id')
    descriptor=os.open(pathlib.Path(store)/digest,os.O_RDONLY|os.O_NOFOLLOW)
    try:
        if not stat.S_ISREG(os.fstat(descriptor).st_mode):raise ValueError('not regular object')
        with os.fdopen(descriptor,'rb',closefd=False) as stream:data=stream.read()
    finally:os.close(descriptor)
    if len(data)!=reference['size'] or hashlib.sha256(data).hexdigest()!=digest:raise ValueError('object checksum/size mismatch')
    return data

def publish_ref(config,topic,store,payload,now):
    root=pathlib.Path(store);root.mkdir(parents=True,exist_ok=True)
    digest=hashlib.sha256(payload).hexdigest();target=root/digest
    reference={'sha256':digest,'size':len(payload),'published_at':now}
    if target.exists():load_ref(store,reference)
    else:
        descriptor,name=tempfile.mkstemp(prefix='.upload-',dir=root)
        try:
            with os.fdopen(descriptor,'wb') as stream:stream.write(payload);stream.flush();os.fsync(stream.fileno())
            os.link(name,target)
        finally:os.unlink(name)
        descriptor=os.open(root,os.O_DIRECTORY)
        try:os.fsync(descriptor)
        finally:os.close(descriptor)
