    if not authority_complete or grace<=0:raise ValueError('complete authority and positive replay grace required')
    messages,_=_scan(config,topic);references=set()
    for message in messages:
        reference=json.loads(message.value());digest=reference['sha256']
        if not re.fullmatch('[0-9a-f]{64}',digest):raise ValueError('invalid retained reference; do not collect')
        references.add(digest)
    deleted=[]
    for path in pathlib.Path(store).iterdir():
        if not re.fullmatch('[0-9a-f]{64}',path.name):continue
        information=path.lstat()
        if not stat.S_ISREG(information.st_mode):continue
        if path.name not in references and now-information.st_mtime>=grace:path.unlink();deleted.append(path.name)
    return sorted(deleted)
